SINA_SMART["anat3-oral-cavity"] = {"lecture":"anat3-oral-cavity","title":"Oral cavity proper, tongue and palate","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat3-oral-cavity:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"anat3-oral-cavity:e0","text":"Oral cavity: lips to the oropharyngeal isthmus; vestibule plus oral cavity proper.","topic":"The oral cavity","sec":1,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e1","text":"Vestibule: between cheeks and gums; buccinator forms its lateral wall; parotid duct opens opposite the upper second molar.","topic":"The oral cavity","sec":1,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e2","text":"Oral cavity proper: roof the hard then soft palate; floor the mylohyoid.","topic":"The oral cavity","sec":1,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e3","text":"Sensory: roof V2 (greater palatine, nasopalatine), floor and cheek V3 (lingual, buccal). Motor to buccinator and orbicularis oris: CN VII.","topic":"The oral cavity","sec":1,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e10","text":"Lymph: tip to submental, anterior two thirds to submandibular, posterior third to deep cervical (jugulodigastric).","topic":"The tongue","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e4","text":"Tongue: three parts, sulcus terminalis with the foramen cecum at its apex, a thyroglossal duct remnant.","topic":"The tongue","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e5","text":"Papillae: filiform, fungiform, vallate on the anterior two thirds; lingual tonsils on the posterior third.","topic":"The tongue","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e6","text":"Intrinsic muscles alter the shape; extrinsic muscles (palatoglossus, genioglossus, hyoglossus, styloglossus) move the tongue.","topic":"The tongue","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e7","text":"Protrusion: genioglossus. Retraction: styloglossus and hyoglossus. Depression: hyoglossus and genioglossus. Elevation: styloglossus and palatoglossus.","topic":"The tongue","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e8","text":"Tongue sensation: V3 lingual (general) and CN VII chorda tympani (taste) anteriorly; CN IX posteriorly; CN X at the base.","topic":"The tongue","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e9","text":"Tongue motor: CN XII for all muscles except palatoglossus, which takes CN X.","topic":"The tongue","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e11","text":"Hard palate: palatine processes of the maxillae plus horizontal plates of the palatine bones.","topic":"The palate","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e12","text":"Palatine aponeurosis is the expanded tendon of tensor veli palatini.","topic":"The palate","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e13","text":"Tensor veli palatini is the only palatine muscle on V3; all the others take the pharyngeal plexus.","topic":"The palate","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e14","text":"Parotid: largest, purely serous, Stensen's duct opposite the upper second molar, CN IX via the otic ganglion.","topic":"The salivary glands","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e15","text":"Submandibular: second largest, mixed but serous predominates, Wharton's duct at the sublingual papilla, CN VII via the submandibular ganglion.","topic":"The salivary glands","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-oral-cavity:e16","text":"Sublingual: smallest, mixed but mucous predominates, ducts of Rivinus along the sublingual fold.","topic":"The salivary glands","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1v9wm06":"a","2geet8":"a","n56l97":"a","ppo1rc":"a","1kc727u":"a","murjv9":"a","1sv3tc1":"a","xehiv":"a","gpetrc":"a","1vzqihs":"a","kcfnx7":"a","1q3i8g3":"a","kwlpis":"a","1gi3u99":"a","1ay7lfw":"a","oxuvij":"a","ny9ata":"a","1g88m51":"a","k700hy":"a","7gd0ac":"a","13mqitg":"a","sf6l6m":"a","1q4ia9d":"a","vv5uw":"a","xc0om4":"a","1ryyp00":"a","v7cd96":"a","n6s15z":"a","lp04k":"a","1bs2y1d":"a","1wdbxdc":"a","rg2udv":"a","1i0yotm":"a","weekdl":"x"},"mapCounts":{"verified":0,"auto":33,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat3-oral-cavity:s0":{"s":0,"u":["The mouth is a box with a bony roof, a muscular floor and a muscular organ in the middle.","Learn its two compartments first, the vestibule outside the teeth and the oral cavity proper inside, then hang everything else on that."],"dp":[]},"anat3-oral-cavity:e0":{"s":1,"u":["Oral cavity: lips to the oropharyngeal isthmus; vestibule plus oral cavity proper.","It is subdivided into the vestibule and the oral cavity proper.","Oral cavity proper: The cavity within the alveolar margins of the maxillae and the mandible."],"dp":[]},"anat3-oral-cavity:e1":{"s":1,"u":["Vestibule: between cheeks and gums; buccinator forms its lateral wall; parotid duct opens opposite the upper second molar.","A small papilla opposite the upper second molar marks the opening of the parotid duct..","Its lateral wall is the cheek, formed by the buccinator, covered laterally by skin and medially by mucous membrane."],"dp":[]},"anat3-oral-cavity:e2":{"s":1,"u":["Oral cavity proper: roof the hard then soft palate; floor the mylohyoid.","Roof: the hard palate anteriorly and the soft palate posteriorly.","It is subdivided into the vestibule and the oral cavity proper."],"dp":[]},"anat3-oral-cavity:e3":{"s":1,"u":["Sensory: roof V2 (greater palatine, nasopalatine), floor and cheek V3 (lingual, buccal). Motor to buccinator and orbicularis oris: CN VII.","Motor: The buccinator in the cheek and the orbicularis oris in the lip, by branches of the facial nerve.","Sensory: roof: Greater palatine and nasopalatine nerves, branches of the maxillary nerve."],"dp":[]},"anat3-oral-cavity:e10":{"s":2,"u":["Lymph: tip to submental, anterior two thirds to submandibular, posterior third to deep cervical (jugulodigastric).","Lymph: tip to the submental nodes bilaterally then deep cervical; anterior two thirds to the submandibular nodes unilaterally then deep cervical; posterior third to the deep cervical nodes, mainly the jugulodigastric.","Three parts: oral (anterior two thirds), pharyngeal (posterior third) and root."],"dp":[{"h":"Clinical","t":"Tongue lymph : tip → submental (both sides); anterior 2/3 → submandibular; posterior 1/3 → deep cervical (jugulodigastric). Tumours near the midline can spread bilaterally."}]},"anat3-oral-cavity:e4":{"s":2,"u":["Tongue: three parts, sulcus terminalis with the foramen cecum at its apex, a thyroglossal duct remnant.","The apex of the sulcus faces backward and is marked by a pit, the foramen cecum , an embryological remnant marking the site of the upper end of the thyroglossal duct.","Divided into anterior two thirds and posterior one third by a V-shaped sulcus terminalis ."],"dp":[{"h":"Note","t":"Foramen caecum at the apex of the sulcus terminalis = origin of the thyroglossal duct (thyroglossal cysts, lingual thyroid). Posterior third has no papillae but the lingual tonsil ."}]},"anat3-oral-cavity:e5":{"s":2,"u":["Papillae: filiform, fungiform, vallate on the anterior two thirds; lingual tonsils on the posterior third.","The anterior two thirds are rough with three types of papillae: filiform, fungiform and vallate .","The posterior third has no papillae but a nodular surface from underlying lymphatic nodules, the lingual tonsils ."],"dp":[]},"anat3-oral-cavity:e6":{"s":2,"u":["Intrinsic muscles alter the shape; extrinsic muscles (palatoglossus, genioglossus, hyoglossus, styloglossus) move the tongue.","They alter the shape of the tongue.","Extrinsic: Connect the tongue to the soft palate and the bones (mandible, hyoid bone, styloid process): palatoglossus, genioglossus, hyoglossus, styloglossus."],"dp":[{"h":"Why a hypoglossal palsy makes the tongue point at the lesion","t":"The genioglossus protrudes the tongue by pulling its root forward, and each side pushes the tongue toward the opposite side. Lose one hypoglossal nerve and the healthy genioglossus is unopposed, so on protrusion the tongue deviates toward the weak side. It is a quick bedside test that follows directly from the muscle's action. Source: the lecture's extrinsic muscle table and its protrusion line."}]},"anat3-oral-cavity:e7":{"s":2,"u":["Protrusion: genioglossus. Retraction: styloglossus and hyoglossus. Depression: hyoglossus and genioglossus. Elevation: styloglossus and palatoglossus.","Depression: Hyoglossus and genioglossus.","Retraction: Styloglossus and hyoglossus."],"dp":[]},"anat3-oral-cavity:e8":{"s":2,"u":["Tongue sensation: V3 lingual (general) and CN VII chorda tympani (taste) anteriorly; CN IX posteriorly; CN X at the base.","Anterior two thirds: General sensation = Lingual nerve (branch of CN V3); Taste = Chorda tympani (CN VII).","Base: General sensation = Internal laryngeal nerve (CN X); Taste = Internal laryngeal nerve (CN X)."],"dp":[{"h":"Why the tongue needs four cranial nerves","t":"The odd nerve supply is embryology showing through. The anterior two thirds come from the first pharyngeal arch, so general sensation follows V3, while taste is carried by CN VII, whose chorda tympani hitches a ride on the lingual nerve. The posterior third comes from the third arch and takes CN IX for both, and the base from the fourth arch takes CN X. The muscles come from occipital somites, which is why they follow CN XII. Source: the lecture's sensory and motor supply slides, read with the three-part division of the tongue."},{"h":"Note","t":"Tongue nerves : anterior 2/3 = lingual (V3) for touch + chorda tympani (VII) for taste; posterior 1/3 = IX for both; base/epiglottis area = X (internal laryngeal)."}]},"anat3-oral-cavity:e9":{"s":2,"u":["Tongue motor: CN XII for all muscles except palatoglossus, which takes CN X.","Motor: the hypoglossal nerve supplies all the muscles; the vagus nerve supplies the palatoglossus.","Elevation: Styloglossus and palatoglossus."],"dp":[{"h":"Note","t":"Motor to the tongue = XII , for every muscle except palatoglossus (X) . Genioglossus protrudes ; styloglossus and hyoglossus retract."}]},"anat3-oral-cavity:e11":{"s":3,"u":["Hard palate: palatine processes of the maxillae plus horizontal plates of the palatine bones.","Formed by the palatine processes of the maxillae in front and the horizontal plates of the palatine bones behind, bounded by the alveolar arches.","The palate lies in the roof of the oral cavity and has two parts: the hard (bony) palate anteriorly and the soft (muscular) palate posteriorly."],"dp":[]},"anat3-oral-cavity:e12":{"s":3,"u":["Palatine aponeurosis is the expanded tendon of tensor veli palatini.","It is the expanded tendon of tensor veli palatini, splits to enclose the musculus uvulae, and gives origin and insertion to the palatine muscles.","Tensor veli palatini: Origin = Spine of sphenoid and auditory tube; Insertion = With the muscle of the other side forms the palatine aponeurosis; Nerve supply = Medial pterygoid nerve of the mandibular nerve; Action = Tenses the soft palate."],"dp":[{"h":"Note","t":"Palate muscles : all on the pharyngeal plexus (X) except tensor veli palatini (V3) . The palatine aponeurosis is the expanded tendon of tensor veli palatini."}]},"anat3-oral-cavity:e13":{"s":3,"u":["Tensor veli palatini is the only palatine muscle on V3; all the others take the pharyngeal plexus.","It is the expanded tendon of tensor veli palatini, splits to enclose the musculus uvulae, and gives origin and insertion to the palatine muscles.","Levator veli palatini: Origin = Petrous part of the temporal bone and auditory tube; Insertion = Palatine aponeurosis; Nerve supply = Pharyngeal plexus; Action = Raises the soft palate."],"dp":[]},"anat3-oral-cavity:e14":{"s":4,"u":["Parotid: largest, purely serous, Stensen's duct opposite the upper second molar, CN IX via the otic ganglion.","Parotid: A serous gland innervated by CN IX parasympathetics that course via the lesser petrosal nerve, synapsing in the otic ganglion, with postganglionics conveyed to the gland in the auriculotemporal nerve (branch of CN V3); secretes via the parotid (Stensen's) duct.","Duct: Stensen's duct crosses the masseter and pierces the buccinator to open at a papilla on the buccal mucosa opposite the maxillary second molar."],"dp":[{"h":"Why mumps hurts to chew","t":"The parotid is wrapped in a tough fascial capsule and sits between the mandible and the mastoid. When it swells, the capsule will not stretch, so pressure rises inside it, and moving the mandible presses on the gland further. The facial nerve running through the gland also explains why parotid surgery risks facial palsy, and why an enlarging parotid mass that causes facial weakness is a worrying sign. Source: the lecture's parotid gland slide, including the facial nerve passing through it."}]},"anat3-oral-cavity:e15":{"s":4,"u":["Submandibular: second largest, mixed but serous predominates, Wharton's duct at the sublingual papilla, CN VII via the submandibular ganglion.","Submandibular: A seromucous gland innervated by CN VII parasympathetics that course to the gland via the chorda tympani branch of CN VII and join the lingual nerve to synapse in the submandibular ganglion (branch of CN V3); secretes via the submandibular (Wharton's) duct.","A mixed gland with both serous and mucous units, but serous units predominate ."],"dp":[{"h":"Why stones form in the submandibular gland","t":"Wharton's duct runs uphill: it travels forward and upward above the mylohyoid to open at the sublingual papilla, so drainage works against gravity. The submandibular saliva is also more viscous and richer in calcium than the parotid's. Those two facts together are why the great majority of salivary stones form here, classically giving pain and swelling under the jaw at mealtimes. Source: the lecture's submandibular duct description and its mixed gland composition."},{"h":"Note","t":"Salivary secretomotor pathways : parotid = IX → lesser petrosal → otic ganglion → auriculotemporal (V3) . Submandibular and sublingual = VII → chorda tympani → lingual → submandibular ganglion ."},{"h":"Note","t":"Gland type: parotid = purely serous (largest); submandibular = mixed, mostly serous ; sublingual = mixed, mostly mucous (smallest). The facial nerve passes through the parotid but does not supply it."}]},"anat3-oral-cavity:e16":{"s":4,"u":["Sublingual: smallest, mixed but mucous predominates, ducts of Rivinus along the sublingual fold.","Its duct opens near the submandibular duct, and several small ducts, the ducts of Rivinus , open independently along the sublingual fold.","A mixed gland, but mucous units predominate ."],"dp":[{"h":"Note","t":"Salivary ducts : parotid (Stensen) opens opposite the upper 2nd molar ; submandibular (Wharton) on the sublingual papilla beside the frenulum; sublingual via many small ducts (Rivinus) on the sublingual fold."}]}},"meta":{"1v9wm06":{"a":"recall","vg":"anat3-oral-cavity:e0/recall/1"},"2geet8":{"a":"recall","vg":"anat3-oral-cavity:e2/recall/1"},"n56l97":{"a":"recall","vg":"anat3-oral-cavity:e1/recall/1"},"ppo1rc":{"a":"recall","vg":"anat3-oral-cavity:e1/recall/2"},"1kc727u":{"a":"recall","vg":"anat3-oral-cavity:e1/recall/3"},"murjv9":{"a":"recall","vg":"anat3-oral-cavity:e0/recall/2"},"1sv3tc1":{"a":"recall","vg":"anat3-oral-cavity:e16/recall/1"},"xehiv":{"a":"recall","vg":"anat3-oral-cavity:e8/recall/1"},"gpetrc":{"a":"recall","vg":"anat3-oral-cavity:e3/recall/1"},"1vzqihs":{"a":"recall","vg":"anat3-oral-cavity:e10/recall/1"},"kcfnx7":{"a":"recall","vg":"anat3-oral-cavity:e4/recall/1"},"1q3i8g3":{"a":"recall","vg":"anat3-oral-cavity:e4/recall/2"},"kwlpis":{"a":"recall","vg":"anat3-oral-cavity:e5/recall/1"},"1gi3u99":{"a":"recall","vg":"anat3-oral-cavity:e5/recall/2"},"1ay7lfw":{"a":"recall","vg":"anat3-oral-cavity:e16/recall/2"},"oxuvij":{"a":"recall","vg":"anat3-oral-cavity:e6/recall/1"},"ny9ata":{"a":"recall","vg":"anat3-oral-cavity:e6/recall/2"},"1g88m51":{"a":"recall","vg":"anat3-oral-cavity:e6/recall/3"},"k700hy":{"a":"recall","vg":"anat3-oral-cavity:e8/recall/1"},"7gd0ac":{"a":"recall","vg":"anat3-oral-cavity:e9/recall/1"},"13mqitg":{"a":"recall","vg":"anat3-oral-cavity:e10/recall/2"},"sf6l6m":{"a":"recall","vg":"anat3-oral-cavity:e11/recall/1"},"1q4ia9d":{"a":"recall","vg":"anat3-oral-cavity:e11/recall/2"},"vv5uw":{"a":"recall","vg":"anat3-oral-cavity:e12/recall/1"},"xc0om4":{"a":"recall","vg":"anat3-oral-cavity:e14/recall/1"},"1ryyp00":{"a":"recall","vg":"anat3-oral-cavity:e14/recall/2"},"v7cd96":{"a":"recall","vg":"anat3-oral-cavity:e15/recall/1"},"n6s15z":{"a":"recall","vg":"anat3-oral-cavity:e16/recall/3"},"lp04k":{"a":"recall","vg":"anat3-oral-cavity:e16/recall/4"},"1bs2y1d":{"a":"recall","vg":"anat3-oral-cavity:e8/recall/1"},"1wdbxdc":{"a":"recall","vg":"anat3-oral-cavity:e6/recall/2"},"rg2udv":{"a":"recall","vg":"anat3-oral-cavity:e15/recall/2"},"1i0yotm":{"a":"recall","vg":"anat3-oral-cavity:e2/recall/2"}},"explRev":"d23ea4373a91"};
